parameters.jsCode:
// Runs once per invoice. Turns AI output into one clean spreadsheet row,
// enforces finance-grade validation, and decides if human review is needed.
let ai = $json.output ?? {};
const file = $('Watch Invoices Folder').item?.json ?? {};
const pdfText = $('Extract PDF Text').item?.json?.text ?? '';

const issues = [];

// 1. Upstream AI API failure handling (e.g. rate limit, network timeout)
if ($json.error) {
  const errorMsg = typeof $json.error === 'object'
    ? ($json.error.message || JSON.stringify($json.error))
    : String($json.error);
  issues.push(`AI API failure: ${errorMsg}`);
}

// 2. Defensive parsing for malformed AI response (string or markdown codeblock)
if (typeof ai === 'string') {
  try {
    const cleaned = ai.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
    ai = JSON.parse(cleaned);
  } catch (e) {
    issues.push('Malformed AI output: could not parse JSON');
    ai = {};
  }
}

// 3. Scanned PDFs have no text layer, so the AI had nothing to read
if (typeof pdfText === 'string' && pdfText.trim().length <= 20) {
  issues.push('No readable text in PDF (scanned image?)');
}

// 4. Fields every invoice must have
for (const field of ['vendor_name', 'invoice_number', 'invoice_date', 'total_amount']) {
  if (ai[field] === null || ai[field] === undefined || String(ai[field]).trim() === '') {
    issues.push(`Missing ${field}`);
  }
}

// 5. Strict calendar date validation (YYYY-MM-DD)
const isValidDate = (d) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d ?? '')) return false;
  const parts = d.split('-').map(Number);
  const dt = new Date(parts[0], parts[1] - 1, parts[2]);
  return dt.getFullYear() === parts[0] && dt.getMonth() === parts[1] - 1 && dt.getDate() === parts[2];
};
if (ai.invoice_date && !isValidDate(ai.invoice_date)) issues.push('Invoice date is not valid YYYY-MM-DD');
if (ai.due_date && !isValidDate(ai.due_date)) issues.push('Due date is not valid YYYY-MM-DD');

// 6. Maths check: subtotal + tax should equal total (allow Rs. 1 for rounding)
const toNumber = (v) =>
  v === null || v === undefined || v === '' ? null : Number(String(v).replace(/,/g, ''));
const subtotal = toNumber(ai.subtotal);
const tax = toNumber(ai.tax_amount);
const total = toNumber(ai.total_amount);
if (subtotal !== null && tax !== null && total !== null && Math.abs(subtotal + tax - total) > 1.0) {
  issues.push(`Subtotal + tax = ${(subtotal + tax).toFixed(2)} but total = ${total.toFixed(2)}`);
}

// 7. GSTIN format: 2-digit state code + 10-character PAN + entity number + Z + check character
const gstin = (ai.vendor_gstin ?? '').toUpperCase().replace(/\s/g, '');
if (gstin && !/^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(gstin)) {
  issues.push('GSTIN format looks wrong');
}

// 8. Duplicate invoice check using n8n workflow static data
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.processedInvoices = staticData.processedInvoices || [];
  const invoiceKey = `${(ai.vendor_name || '').trim().toLowerCase()}_${(ai.invoice_number || '').trim().toLowerCase()}`;
  if (ai.invoice_number && staticData.processedInvoices.includes(invoiceKey)) {
    issues.push('Duplicate invoice detected: already processed previously');
  } else if (ai.invoice_number && issues.length === 0) {
    staticData.processedInvoices.push(invoiceKey);
    if (staticData.processedInvoices.length > 500) staticData.processedInvoices.shift();
  }
} catch (e) {
  // Static data not available in manual single-node test runs
}

// Column names here become the Google Sheet headers (Auto-Map in the next node)
return {
  json: {
    'Processed At': $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm'),
    'File Name': file.name ?? '',
    'File Link': file.webViewLink ?? (file.id ? `https://drive.google.com/file/d/${file.id}/view` : ''),
    'Vendor': ai.vendor_name ?? '',
    'GSTIN': gstin,
    'Invoice No': ai.invoice_number ?? '',
    'Invoice Date': ai.invoice_date ?? '',
    'Due Date': ai.due_date ?? '',
    'Currency': ai.currency ?? 'INR',
    'Subtotal': subtotal ?? '',
    'Tax': tax ?? '',
    'Total': total ?? '',
    'Category': ai.category ?? 'Other',
    'Status': issues.length ? 'Needs review' : 'OK',
    'Review Notes': issues.join('; '),
  },
};
